export const meta = {
  name: 'review-mm02',
  description: 'Adversarial spec-fidelity review of formal/Ern/MM02.lean against ERN MM-02 v0.2 and the task prompt',
  phases: [
    { title: 'Find', detail: 'five finders, one per rule group / concern' },
    { title: 'Verify', detail: 'three refuters per finding, distinct lenses' },
    { title: 'Inventory', detail: 'independent list of modelling decisions and spec/task issues' },
  ],
}

const REPO = '/Users/guygouri/Devlab/ernlang/ern'
const LEAN = REPO + '/formal/Ern/MM02.lean'
const SPEC = '/Users/guygouri/Downloads/ERN_Memory_model.md'
const TASK = '/private/tmp/claude-501/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/scratchpad/task.md'
const SCRATCH = '/private/tmp/claude-501/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/scratchpad'

const COMMON = `
You are an adversarial, READ-ONLY reviewer of a Lean 4 formalization. Never edit, create or delete any file under ${REPO}. Never run git commands that change state.
Read IN FULL before judging anything:
- The Lean module under review: ${LEAN}
- The normative spec (French), section MM-02 only is in scope: ${SPEC}
- The task prompt that governs this pass (French): ${TASK}
- Formalization design rules: ${REPO}/formal/DESIGN.md
Context you must apply:
- The task prompt explicitly allows taking the WEAKEST reading of an ambiguous or incomplete rule provided it is logged in the report, and explicitly allows abstracting some read/write conditions "par omission". So an interpretation is a defect only if (i) it is not the weakest reading, (ii) it adds a rule the spec does not state, (iii) it makes a definition more permissive or more restrictive than the spec text in a way the task does not authorize, or (iv) a theorem holds only because a definition is too permissive or its hypotheses are unsatisfiable. Still list every interpretation you notice as a 'silent interpretation' note so it can be documented.
- Spec beats code. Charter > spec > formalization. Nothing beyond the task's scope may be requested.
- Toolchain: Lean 4.35.0, core only (no Mathlib, no Batteries). You MAY test claims in Lean: write scratch files ONLY under ${SCRATCH}/ with a filename unique to you, starting with 'import Ern.MM02' and 'open Ern.MM02', then run from ${REPO}/formal:   lake env lean <absolute path to your scratch file>
  (the library is already built; do not run lake build unless your brief says so).
Evidence rule: every finding needs evidence, i.e. a verbatim French quote of the spec or task passage, a concrete counterexample (explicit State / Alloc / Access values, ideally checked in Lean with command output), or command output. No evidence, no finding. No style remarks. No requests for additions beyond the task.
Severity: 'block' = theorem or definition is wrong w.r.t. the spec/task; 'changes' = must be fixed before the pass is done (missing docstring, missing scope item, wrong name, wrong quantification); 'note' = an interpretation or limitation that must only be documented in the report.
Return ONLY the structured object. Keep each field terse and concrete.`

const FINDINGS = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          location: { type: 'string', description: 'Lean declaration name and/or file:line' },
          severity: { type: 'string', enum: ['block', 'changes', 'note'] },
          cause: { type: 'string', enum: ['formalization error', 'missing coverage', 'spec defect', 'task ambiguity', 'silent interpretation'] },
          claim: { type: 'string', description: 'one or two sentences: what is wrong or what was chosen' },
          evidence: { type: 'string', description: 'verbatim quote, counterexample or command output' },
          fix: { type: 'string', description: 'smallest change that would resolve it, if any' },
        },
        required: ['title', 'location', 'severity', 'cause', 'claim', 'evidence'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT = {
  type: 'object',
  properties: {
    refuted: { type: 'boolean' },
    reason: { type: 'string' },
  },
  required: ['refuted', 'reason'],
}

const INVENTORY = {
  type: 'object',
  properties: {
    decisions: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          decision: { type: 'string' },
          where: { type: 'string', description: 'Lean declaration(s)' },
          spec_sentence: { type: 'string', description: 'verbatim French sentence of MM-02 the decision concerns' },
          alternatives: { type: 'string' },
        },
        required: ['decision', 'where', 'spec_sentence'],
      },
    },
    spec_issues: {
      type: 'array',
      items: {
        type: 'object',
        properties: { issue: { type: 'string' }, passage: { type: 'string' } },
        required: ['issue', 'passage'],
      },
    },
    task_issues: {
      type: 'array',
      items: {
        type: 'object',
        properties: { issue: { type: 'string' }, passage: { type: 'string' } },
        required: ['issue', 'passage'],
      },
    },
  },
  required: ['decisions', 'spec_issues', 'task_issues'],
}

const FINDERS = [
  {
    key: 'data-model',
    brief: `Scope: MM-02.2 (Alloc, State), MM-02.3 (AByte), MM-02.4 (Place), MM-02.5 (Access, Auth and its LE instance).
For each structure: does it have exactly the components the spec lists AND the task's "Périmètre" bullets name, no invented field, no missing in-scope field? Is each Nat's role documented? Is 'LE Auth' exactly read ≤ write, reflexive, and is 'write ≤ read' false (test it in Lean)? Is Place distinct from Access and does it carry 'allocation + plage'? Does AByte match 'uninit | init (valeur) (provenance optionnelle)'? Is the allocation's identity represented (as the key of State.allocs) in a way faithful to "Une identité unique"? Is 'freeAuth : Option Nat' a faithful reading of "Une relation avec les autorités capables de la désallouer, lorsque la désallocation est applicable" and of the task's "autorité de désallocation"?`,
  },
  {
    key: 'identity-dealloc',
    brief: `Scope: MM-02.A and MM-02.D: WF, alloc, dealloc, CanDealloc, alloc_fresh, alloc_wf, dealloc_wf, write_wf, dealloc_invalidates, reuse_does_not_restore, no_double_free.
Check: non-reuse of identity follows from the definitions; an address CAN be reused after dealloc in the model (exhibit a Lean example where a new allocation has the same base as a dead one); reuse_does_not_restore quantifies base universally and admits base = old base (the task says a version with a different base is worthless); CanDealloc models "Une allocation vivante et désallouable par l'opération concernée" and "Une autorité compatible avec les conditions de désallocation" via the parametric Compatible, not equality; dealloc's effect realises "Une désallocation réussie termine la validité du stockage concerné"; dealloc_invalidates and no_double_free have NO precondition hypothesis (the effect function is total): decide with evidence whether that makes them stronger-than-spec in a harmless way or whether it hides a defect; whether each theorem holds for the right reason (try a mutated definition in a scratch file and see whether the theorem would still go through).`,
  },
  {
    key: 'read-write',
    brief: `Scope: MM-02.B and MM-02.C: Spatial, Alloc.InitRange, Read, CanWrite, Alloc.write, write, read_requires_live, write_initializes.
Check: B conditions 1, 2, 3, 5 and C conditions 1, 2, 3 are each present as a conjunct and say what the spec says, no more, no less; B.5 'autorité de lecture valide' is trivially true with only {read, write} — say whether that is a faithful consequence of the task's authority lattice or a defect; which conditions are abstracted by omission and whether that matches the task (note the task says for C "1, 2, 3, 5, 6 modélisées ; 4 abstraite" while the module omits C.4, C.5, C.6 — assess whether C.5 alignment and C.6 concurrency COULD be modelled without inventing a rule, given MM-02.2's 'alignement' field and that MM-02.F is out of scope); spatial validity is inclusion of the half-open access range in the allocation extent; initialization is tracked per byte ("granularité permettant de représenter les allocations partiellement initialisées"); Alloc.write updates exactly the written range and leaves other bytes unchanged (prove or refute in Lean); write_initializes states "L'écriture met à jour les octets et les états d'initialisation correspondants" and "peut initialiser un emplacement précédemment non initialisé"; the written data type Nat → Nat × Option Nat (value, provenance per byte) is faithful to MM-02.3; offsets vs addresses: bytes are indexed by offset from base while Access carries an address, check every subtraction ac.addr - a.base is guarded by Spatial where it matters.`,
  },
  {
    key: 'derive-vacuity',
    brief: `Scope A: MM-02.E: Derive, derive_spatial, derive_prov, derive_auth_le. Check Derive says 'sous-plage, même provenance, autorité ≤ origine' and nothing else; that out-of-bounds formation is NOT classified as UB (the task forbids modelling it as UB); that derive_spatial is the meaningful statement (a derived access of a spatially valid access is spatially valid).
Scope B, for ALL 12 theorems of the module (read_requires_live, dealloc_invalidates, reuse_does_not_restore, no_double_free, write_initializes, derive_spatial, derive_prov, derive_auth_le, alloc_fresh, alloc_wf, dealloc_wf, write_wf): vacuity and triviality audit. For each: (1) are the hypotheses satisfiable? Exhibit a concrete Lean witness (e.g. a State with one live allocation and an Access satisfying Read; a WF state) in a scratch file and check it elaborates. (2) Does the theorem hold only because a definition is too permissive? (3) Does it actually state the claim named in the task (P1: read requires live; P2a: dealloc invalidates; P2b: reuse of the SAME base does not restore; P2c: no double free; P3: write initializes; P4: derivation keeps spatial validity, provenance, auth ≤; freshness invariant preserved)? (4) Mutation test: describe one plausible wrong definition (e.g. dealloc that does not clear 'live', alloc that reuses an id, Derive without the prov clause) and say whether the theorem would catch it. Report only concrete problems; a theorem that is a direct projection of a definition is acceptable when the task names it, but say so as a 'note'.`,
  },
  {
    key: 'task-compliance',
    brief: `Scope: compliance of the repository state with EVERY bullet of the task prompt and with ${REPO}/AGENTS.md and ${REPO}/formal/DESIGN.md. From ${REPO}: run 'git branch --show-current', 'git status --short', 'git diff main --stat' and 'git diff main' (read-only) and check: branch is formal/memory_model_0.2; every changed or new file is under formal/; the spec text was NOT copied into the repo (search for distinctive spec sentences under formal/); module path and name follow the existing convention (Ern library, globs Ern.*, root Ern.lean) given the task's 'ERN/MM02.lean ou l'emplacement équivalent selon la convention existante'; no 'abbrev' for numeric types; only core imports; every def, theorem AND instance carries a docstring citing an MM-02.x rule; all imposed theorem names exist with the stated meaning; nothing out of scope (MM-02.F, MM-02.G, MM-03, MM-02.1) is modelled; nothing beyond the task was added; no sorry/admit/axiom/native_decide (run: grep -rnE '\\b(sorry|admit|native_decide)\\b|^\\s*axiom\\b' --include='*.lean' --exclude-dir=.lake . from formal/); 'lake build' passes with zero warnings (run it from formal/); '#print axioms' of each of the 12 theorems is within {propext, Quot.sound, Classical.choice} (run it via a scratch file). Also check DESIGN.md constraints that apply (no Mathlib; step FUNCTION where the spec is deterministic; docstrings cite rules; nothing restates spec content in comments, only cites locations). Report each violated bullet as a finding; do not report satisfied bullets.`,
  },
]

const LENSES = [
  { key: 'spec-text', brief: 'Lens: the SPEC TEXT. Re-read the exact MM-02 passage(s) the finding relies on and decide whether the spec actually says what the finding claims. A finding that attributes to the spec something the spec does not say, or that treats as a defect something the task prompt explicitly permits (weakest reading logged in the report, abstraction by omission), is refuted.' },
  { key: 'lean-semantics', brief: 'Lens: the LEAN CODE. Check that the module really behaves as the finding claims: reproduce the counterexample or the claimed property in a scratch file and run Lean. A finding whose claimed counterexample does not elaborate, or whose claimed behaviour is not what the definitions do, is refuted.' },
  { key: 'task-scope', brief: 'Lens: the TASK PROMPT, AGENTS.md and DESIGN.md. Decide whether the finding is in scope of this pass and whether it is a defect to fix, a decision to document in the report, or out of scope. Something the task explicitly authorizes, or that only asks for an addition beyond the task, is refuted as a defect (it may still be a report note).' },
]

phase('Find')
const inventoryP = agent(`${COMMON}
Your job: produce an INVENTORY, not a verdict. (1) List every modelling decision in ${LEAN} that the MM-02 text does not dictate (representation of the allocation map and identity, total effect functions, offset-indexed bytes, Auth order encoding, Option freeAuth, Place unused by operations, written data type, half-open ranges, truncated subtraction, which conditions are abstracted and how, unconditional forms of theorems, etc.), each with the verbatim French spec sentence it concerns and the alternatives. (2) List spec issues inside MM-02 (ambiguity, contradiction, silence on something the formalization needed), each with the passage. (3) List task-prompt issues (e.g. the C.5/C.6 wording vs B.6/B.7, module name ERN vs Ern), each with the passage. Be exhaustive; this feeds the report sections (c) and (e).`,
  { label: 'inventory', phase: 'Inventory', schema: INVENTORY })

const results = await pipeline(
  FINDERS,
  f => agent(`${COMMON}
Finder '${f.key}'. ${f.brief}`, { label: `find:${f.key}`, phase: 'Find', schema: FINDINGS }),
  (found, f) => {
    const list = (found && found.findings) || []
    log(`find:${f.key} → ${list.length} finding(s)`)
    return parallel(list.map(fd => () =>
      parallel(LENSES.map(l => () => agent(`${COMMON}
${l.brief}
Finding under review (from finder '${f.key}'):
title: ${fd.title}
location: ${fd.location}
severity: ${fd.severity}
cause: ${fd.cause}
claim: ${fd.claim}
evidence: ${fd.evidence}
proposed fix: ${fd.fix || '(none)'}
Try hard to REFUTE this finding through your lens. If you cannot refute it with evidence, set refuted=false and say what evidence confirms it. If uncertain, set refuted=true. Give the reason in two or three sentences.`,
        { label: `verify:${f.key}:${l.key}`, phase: 'Verify', schema: VERDICT })))
        .then(vs => {
          const votes = vs.filter(Boolean)
          const notRefuted = votes.filter(v => !v.refuted).length
          return { ...fd, finder: f.key, survives: notRefuted >= 2, votes }
        })
    ))
  }
)

const all = results.filter(Boolean).flat().filter(Boolean)
const confirmed = all.filter(x => x.survives)
const rejected = all.filter(x => !x.survives)
log(`${confirmed.length} confirmed, ${rejected.length} rejected`)
const inventory = await inventoryP
return { confirmed, rejected, inventory }

