export const meta = {
  name: 'rereview-mm02',
  description: 'Targeted refutation review of the committed MM-02 module and report: changed theorem statements, report facts, report spec fidelity',
  phases: [
    { title: 'Find', detail: 'three independent finders' },
    { title: 'Verify', detail: 'three lenses for block/changes, one for notes' },
  ],
}

const REPO = '/Users/guygouri/Devlab/ernlang/ern'
const LEAN = REPO + '/formal/Ern/MM02.lean'
const REPORT = REPO + '/formal/reports/MM02_v0.2.md'
const SPEC = '/Users/guygouri/Downloads/ERN_Memory_model.md'
const TASK = '/private/tmp/claude-501/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/scratchpad/task.md'
const SCRATCH = '/private/tmp/claude-501/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/scratchpad'

const COMMON = `
You are an adversarial, READ-ONLY reviewer of a Lean 4 formalization and its report. Never edit, create or delete any file under ${REPO}. Never run git commands that change state (read-only git log/show/diff/status are fine).
Read IN FULL before judging:
- The Lean module, committed on branch formal/memory_model_0.2: ${LEAN}
- The report that will be sent back to the task author (French): ${REPORT}
- The normative spec (French); only MM-02 is in scope: ${SPEC}
- The task prompt governing this pass (French): ${TASK}
- ${REPO}/AGENTS.md and ${REPO}/formal/DESIGN.md
Rules you must apply:
- The task allows the WEAKEST reading of an ambiguous or incomplete rule provided it is logged in the report, and allows abstracting some read/write conditions by omission. An interpretation is a defect only if (i) it is not the weakest reading, (ii) it adds a rule the spec does not state, (iii) a definition is more permissive or more restrictive than the spec text in a way the task does not authorize, (iv) a theorem holds only because a definition is too permissive or its hypotheses are unsatisfiable, or (v) it is not logged in the report.
- The task says "Rien au-delà du périmètre" and AGENTS.md says "Do exactly the task. No unrequested features". A theorem statement STRONGER than what the task names can be a scope defect; judge it.
- Spec beats code. Charter > spec > formalization.
- Toolchain Lean 4.35.0, core only. You MAY test claims in Lean: write scratch files ONLY under ${SCRATCH}/ with a filename unique to you (prefix it with 'rr_'), starting with 'import Ern.MM02' and 'open Ern.MM02', then run from ${REPO}/formal:  lake env lean <absolute path>
  The library is built; run 'lake build' only if your brief says so.
Evidence rule: every finding needs evidence: a verbatim French quote of the spec, task or report, a concrete counterexample (checked in Lean, with output), or command output. No evidence, no finding. No style remarks. No requests for additions beyond the task.
Severity: 'block' = a theorem, definition or report statement is wrong w.r.t. spec/task/code; 'changes' = must be fixed before the report is sent (false claim in the report, scope violation, missing required item, interpretation not logged); 'note' = imprecision worth a one-line fix but not wrong.
Return ONLY the structured object; terse and concrete.`

const FINDINGS = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          location: { type: 'string', description: 'Lean declaration and/or file:line, or report section' },
          severity: { type: 'string', enum: ['block', 'changes', 'note'] },
          cause: { type: 'string', enum: ['formalization error', 'scope', 'false report claim', 'missing coverage', 'spec defect', 'unlogged interpretation'] },
          claim: { type: 'string' },
          evidence: { type: 'string' },
          fix: { type: 'string' },
        },
        required: ['title', 'location', 'severity', 'cause', 'claim', 'evidence'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT = {
  type: 'object',
  properties: { refuted: { type: 'boolean' }, reason: { type: 'string' } },
  required: ['refuted', 'reason'],
}

const FINDERS = [
  {
    key: 'changed-statements',
    brief: `Scope: these declarations were written or restated AFTER an earlier review and have never been reviewed: dealloc_dead, dealloc_invalidates, no_double_free, reuse_does_not_restore, alloc_fresh, plus the docstrings of Alloc (freeAuth), Access (prov) and the module header.
For each theorem: (1) is the statement faithful to the spec rule it cites, not stronger and not weaker? (2) Is it within the task's scope? The task lists by name 'dealloc_invalidates' (P2a), 'reuse_does_not_restore' (P2b), 'alloc_fresh' without spelling out their statements; decide with quotes whether concluding '¬ Read ∧ ¬ CanWrite' and adding a preservation clause to alloc_fresh is within scope or 'au-delà du périmètre', and whether the extra lemma dealloc_dead is acceptable. (3) For reuse_does_not_restore: is base universally quantified and can it equal the old allocation's base (exhibit it in Lean)? Are the hypotheses WF and existence both necessary (give counterexamples without each) and satisfiable? (4) Mutation tests: an alloc that reuses an identity, a dealloc that does not clear live, a CanWrite without the live conjunct: does some theorem catch each? (5) Do the docstrings cite the right MM-02 rule and describe the statement accurately?`,
  },
  {
    key: 'report-facts',
    brief: `Scope: every factual claim the REPORT makes about the code. Go through the report line by line. For each claim about what the module defines, states, permits or proves, check it in Lean or by reading the code. In particular check: the list of declarations in table (a) exists with those names; each one-sentence theorem summary matches the Lean statement exactly (hypotheses and conclusion); the consequences listed in (c) 4, 5, 6, 7, 12, 13 (dealloc of an unknown or dead id changes nothing; write outside spatial validity still writes, offset truncated to 0 when addr < base; zero-length access valid on [base, base+size] and readable on an all-uninit allocation; overlapping live allocations allowed; align 0 allowed); the claims in (d) (without WF the new allocation could reuse the identity; without prior existence a never-allocated identity could be next; an identity-reusing alloc mutant breaks reuse_does_not_restore via a zero-length read; alloc_fresh rejects an identity-reusing alloc; write_initializes only uses the existence part of CanWrite; frame property is definitional; B.5 never filters); and the header bullets (run 'lake build' from ${REPO}/formal and count warnings, run the forbidden-token grep from AGENTS.md, run '#print axioms' on every theorem). Report every claim that is false or imprecise. Do not report claims that are true.`,
  },
  {
    key: 'report-spec',
    brief: `Scope: the REPORT's relation to the spec and the task. Check: (1) every French quote attributed to the spec is verbatim and attached to the right rule (grep the spec); (2) every interpretation in (c) is the weakest available reading, or is flagged as not being one; (3) every arbitration question in (e) is genuine (the spec really is silent, ambiguous or contradictory there; quote it) and none is missing for a place where the module had to choose; (4) sections (a) to (e) required by the task are all present and say what the task asks; (5) the report attributes nothing to the spec that the spec does not say, and nothing to the task that the task does not say; (6) completeness: list every modelling decision visible in the module that the report does not mention at all.`,
  },
]

const LENSES = [
  { key: 'spec-text', brief: 'Lens: the SPEC and TASK TEXT. Re-read the exact passages the finding relies on and decide whether they say what the finding claims. A finding that attributes to the spec or task something they do not say, or treats as a defect what the task explicitly permits, is refuted.' },
  { key: 'lean-semantics', brief: 'Lens: the LEAN CODE and the REPORT TEXT. Reproduce the claimed behaviour or counterexample in a scratch file and run Lean, and re-read the exact report sentence if the finding is about the report. A finding whose counterexample does not elaborate, or whose claimed behaviour or quoted report text is not what the files contain, is refuted.' },
  { key: 'task-scope', brief: 'Lens: SCOPE, per the task prompt, AGENTS.md and DESIGN.md. Decide whether the finding is a real defect to fix before the report is sent, merely a note, or out of scope. A finding that only asks for an addition beyond the task is refuted.' },
]

const verifyPrompt = (fd, key, l) => `${COMMON}
${l.brief}
Finding under review (from finder '${key}'):
title: ${fd.title}
location: ${fd.location}
severity: ${fd.severity}
cause: ${fd.cause}
claim: ${fd.claim}
evidence: ${fd.evidence}
proposed fix: ${fd.fix || '(none)'}
Try hard to REFUTE it through your lens. If you cannot refute it with evidence, set refuted=false and give the confirming evidence. If uncertain, set refuted=true. Two or three sentences.`

const results = await pipeline(
  FINDERS,
  f => agent(`${COMMON}
Finder '${f.key}'. ${f.brief}`, { label: `find:${f.key}`, phase: 'Find', schema: FINDINGS }),
  (found, f) => {
    const list = (found && found.findings) || []
    log(`find:${f.key} → ${list.length} finding(s)`)
    return parallel(list.map(fd => () => {
      // notes get one combined verifier; block/changes get all three lenses
      const lenses = fd.severity === 'note' ? [LENSES[1]] : LENSES
      return parallel(lenses.map(l => () =>
        agent(verifyPrompt(fd, f.key, l), { label: `verify:${f.key}:${l.key}`, phase: 'Verify', schema: VERDICT })))
        .then(vs => {
          const votes = vs.filter(Boolean)
          const kept = votes.filter(v => !v.refuted).length
          const need = lenses.length === 1 ? 1 : 2
          const status = votes.length < need ? 'unverified' : (kept >= need ? 'confirmed' : 'refuted')
          return { ...fd, finder: f.key, status, expected: lenses.length, votes }
        })
    }))
  }
)

const all = results.filter(Boolean).flat().filter(Boolean)
