export const meta = {
  name: 'review-mm02-v03',
  description: 'Adversarial review of the MM-02 v0.3 Lean module and its report against the v0.3 spec, the task prompt and DESIGN.md',
  phases: [
    { title: 'Find', detail: 'four independent finders' },
    { title: 'Verify', detail: 'three lenses for block/changes, one for notes' },
  ],
}

const REPO = '/Users/guygouri/Devlab/ernlang/ern'
const LEAN = REPO + '/formal/Ern/MM02.lean'
const REPORT = REPO + '/formal/reports/MM02_v0.3.md'
const SPEC = '/Users/guygouri/Downloads/ERN_Memory_Model_v0.3_consolidee.md'
const TASK = '/private/tmp/claude-501/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/scratchpad/task03.md'
const SCRATCH = '/private/tmp/claude-501/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/scratchpad'

const COMMON = `
You are an adversarial, READ-ONLY reviewer of a Lean 4 formalization and its report. Never edit, create or delete any file under ${REPO}. Never run git commands that change state (read-only git log/show/diff/status are fine).
Read IN FULL before judging:
- The Lean module on branch formal/memory_model_0.3 (working tree): ${LEAN}
- The previous version, for comparison: git -C ${REPO} show formal/memory_model_0.2:formal/Ern/MM02.lean
- The report (French; the module is committed, the report is not yet committed): ${REPORT}
- The normative spec v0.3 (French); MM-01 and MM-02 incl. MM-02.H and the "Obligations de preuve" section: ${SPEC}
- The task prompt governing this pass (French): ${TASK}
- ${REPO}/AGENTS.md and ${REPO}/formal/DESIGN.md
Rules you must apply:
- Hierarchy: Charte > spec > formalization. The task prompt directs the formalization; where the prompt and the spec conflict, the spec wins and the conflict must be reported in the report.
- A definition must say what its rule says: not more permissive, not more restrictive. A theorem that holds because a definition is too permissive, or whose hypotheses are unsatisfiable, is blocking. A v0.2 statement must not be weakened; a changed statement must be explained in the report.
- Every modelling decision not dictated by the spec text must appear in report section (c) with the spec sentence it concerns.
- "Do exactly the task": additions beyond the task are a scope defect unless needed for a required item.
- Toolchain Lean 4.35.0, core only. You MAY test claims in Lean: write scratch files ONLY under ${SCRATCH}/ with a filename unique to you (prefix 'v3_'), starting with 'import Ern.MM02' and 'open Ern.MM02', then run from ${REPO}/formal:  lake env lean <absolute path>
  The library is built; run 'lake build' only if your brief says so.
Evidence rule: every finding needs evidence: a verbatim French quote of the spec, task or report, a concrete counterexample checked in Lean with its output, or command output. No evidence, no finding. No style remarks. No requests for additions beyond the task.
Severity: 'block' = a theorem, definition or report statement is wrong w.r.t. spec/task/code; 'changes' = must be fixed before delivery (false claim, scope violation, missing required item, unlogged interpretation, weakened v0.2 statement); 'note' = imprecision worth a one-line fix.
Return ONLY the structured object; terse and concrete.`

const FINDINGS = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          location: { type: 'string', description: 'Lean declaration and/or file:line, or report section' },
          severity: { type: 'string', enum: ['block', 'changes', 'note'] },
          cause: { type: 'string', enum: ['formalization error', 'scope', 'false report claim', 'missing coverage', 'spec defect', 'unlogged interpretation', 'weakened statement'] },
          claim: { type: 'string' },
          evidence: { type: 'string' },
          fix: { type: 'string' },
        },
        required: ['title', 'location', 'severity', 'cause', 'claim', 'evidence'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT = {
  type: 'object',
  properties: { refuted: { type: 'boolean' }, reason: { type: 'string' } },
  required: ['refuted', 'reason'],
}

const FINDERS = [
  {
    key: 'module-spec',
    brief: `Scope: fidelity of every v0.3 definition and theorem to the spec and the task. Check in particular, with Lean experiments: RangeDisjoint and LiveDisjoint against MM-02.2 (half-open, empty range overlaps nothing, same space only, distinct live allocations); AllocPre against « Création brute » (freshness, alignment strictly positive power of two, base aligned, LiveDisjoint) and against the task's alloc precondition; Access.toPlace against MM-02.4 and the task's signature 'State → Access → Option Place' and its 'some ssi' clause; ReadPlace/CanWritePlace and the equivalences; Outcome/Outcome' and the raw and checked operations against MM-02.H, MM-01.3, MM-01.5 and the task (constructors, 'ok quand la précondition est satisfaite, ub sinon', 'fail rendu au lieu d'entrer dans l'opération'); the explicit obligation parameters ObR/ObW versus the task's « abstraits comme en v0.2 » and the spec's scope sentence about not replacing obligations by True: decide whether this is the right call or a deviation; the restated dealloc_invalidates, no_double_free, reuse_does_not_restore against the task's wording and MM-02.A/D (is base universally quantified and may it equal the old base? are hypotheses satisfiable?); the frame lemmas against the task's exact list and MM-02.C/A; whether any v0.2 theorem was weakened (compare statements with the v0.2 file). Mutation-test each new theorem: describe a plausible wrong definition and check whether the theorem catches it.`,
  },
  {
    key: 'task-compliance',
    brief: `Scope: compliance with every bullet of the task prompt, AGENTS.md and DESIGN.md. From ${REPO} run read-only: git branch --show-current; git log --oneline formal/memory_model_0.2..HEAD; git merge-base --is-ancestor formal/memory_model_0.2 HEAD && echo ancestor; git diff --stat formal/memory_model_0.2 HEAD; git status --short. Check: branch created from formal/memory_model_0.2; one atomic French commit per step in the prompt's order; every change under formal/; spec not copied into the repo (search formal/ for distinctive spec sentences, excluding the report's short quotes); core Lean only; 'lake build' from formal/ passes with zero warnings (run it); the forbidden-token grep from AGENTS.md prints nothing (run it); '#print axioms' on EVERY theorem is within {propext, Quot.sound, Classical.choice} (generate a scratch file listing all theorems and run it); every def, theorem, instance and inductive carries a docstring citing an MM-02.x or MM-01.x rule; required names exist with the required types (Alloc.space, AByte value 8-bit, LiveDisjoint, Access.toPlace : State → Access → Option Place, read_iff_place, canWrite_iff_place, Outcome with exactly ok (s : State) | ub, raw read/write/dealloc/alloc ending in State → Outcome, checkedWrite, checkedDealloc, Outcome' with fail, a never-ub theorem, dealloc_invalidates, no_double_free, reuse_does_not_restore on outcomes, write_frame, dealloc_frame, alloc_frame); nothing out of scope implemented (carve/uncarve, arena.reset, sub-objects, generations, revoke/merge, defer, MVS). Report only violations.`,
  },
  {
    key: 'report-facts',
    brief: `Scope: every factual claim the REPORT makes about the code and the repository. Go through the report line by line and check each claim in Lean or by reading the code: the header bullets (build, warnings, axioms, theorem count, which theorems use Classical.choice); the v0.2→v0.3 change table (each listed change and its reason; are there statement changes it misses? compare with the v0.2 file); every table (a) row names existing declarations that do what the row says; every one-sentence theorem summary matches the Lean statement exactly (hypotheses and conclusion); every consequence claimed in (c) (e.g. zero-size allocation creatable inside a live allocation of the same space; freshness can only fail outside WF; State.alloc alone accepts any alignment; toPlace resolves dead allocations; a weaker check would falsify checkedWrite_ne_ub; reuse_does_not_restore's proof does not use base; instantiating ObR/ObW with True gives back v0.2's omission); every claim in (d). Report every false or imprecise claim; do not report true ones.`,
  },
  {
    key: 'report-spec',
    brief: `Scope: the REPORT's relation to the spec v0.3, the task and DESIGN.md. Check: every French quote attributed to the spec, the task or DESIGN.md is verbatim (grep; ignore markdown bold) and attached to the right rule; every (c) item carries a spec sentence and states a real decision; every interpretation is the weakest available or is flagged; every (e) question is genuine (quote the passage) and none is missing where the module had to choose; section (b) lists what spec obligation 8 requires; section (f) states DESIGN.md correctly and misses no real conflict; the report attributes nothing to the spec or task they do not say; the table (a) covers every normative sentence of MM-02.2 to MM-02.E and MM-02.H in scope (list the uncovered ones); sections (a) to (f) required by the task are present and do what the task asks.`,
  },
]

const LENSES = [
  { key: 'spec-text', brief: 'Lens: the SPEC, TASK and DESIGN TEXT. Re-read the exact passages the finding relies on and decide whether they say what the finding claims. A finding that attributes to them something they do not say, or treats as a defect what they explicitly permit, is refuted.' },
  { key: 'lean-semantics', brief: 'Lens: the LEAN CODE and the REPORT TEXT. Reproduce the claimed behaviour or counterexample in a scratch file and run Lean, and re-read the exact report sentence if the finding is about the report. A finding whose counterexample does not elaborate, or whose claimed behaviour or quoted text is not what the files contain, is refuted.' },
  { key: 'task-scope', brief: 'Lens: SCOPE, per the task prompt, AGENTS.md and DESIGN.md. Decide whether the finding is a real defect to fix before delivery, merely a note, or out of scope. A finding that only asks for an addition beyond the task is refuted.' },
]

const verifyPrompt = (fd, key, l) => `${COMMON}
${l.brief}
Finding under review (from finder '${key}'):
title: ${fd.title}
location: ${fd.location}
severity: ${fd.severity}
cause: ${fd.cause}
claim: ${fd.claim}
evidence: ${fd.evidence}
proposed fix: ${fd.fix || '(none)'}
Try hard to REFUTE it through your lens. If you cannot refute it with evidence, set refuted=false and give the confirming evidence. If uncertain, set refuted=true. Two or three sentences.`

const results = await pipeline(
  FINDERS,
  f => agent(`${COMMON}
Finder '${f.key}'. ${f.brief}`, { label: `find:${f.key}`, phase: 'Find', schema: FINDINGS }),
  (found, f) => {
    const list = (found && found.findings) || []
    log(`find:${f.key} → ${list.length} finding(s)`)
    return parallel(list.map(fd => () => {
      const lenses = fd.severity === 'note' ? [LENSES[1]] : LENSES
      return parallel(lenses.map(l => () =>
        agent(verifyPrompt(fd, f.key, l), { label: `verify:${f.key}:${l.key}`, phase: 'Verify', schema: VERDICT })))
        .then(vs => {
          const votes = vs.filter(Boolean)
          const kept = votes.filter(v => !v.refuted).length
          const need = lenses.length === 1 ? 1 : 2
          const status = votes.length < need ? 'unverified' : (kept >= need ? 'confirmed' : 'refuted')
          return { ...fd, finder: f.key, status, expected: lenses.length, votes }
        })
    }))
  }
)

const all = results.filter(Boolean).flat().filter(Boolean)
const by = s => all.filter(x => x.status === s)
log(`${by('confirmed').length} confirmed, ${by('refuted').length} refuted, ${by('unverified').length} unverified`)
return { confirmed: by('confirmed'), refuted: by('refuted'), unverified: by('unverified') }

